@inline function _nas_fdkg_finite(x::Float64)
    return isfinite(x) ? x : 0.0
end

function _nas_fdkg_metrics(coords::AbstractMatrix, Cb)
    e12x = Float64(coords[2, 1] - coords[1, 1])
    e12y = Float64(coords[2, 2] - coords[1, 2])
    e23x = Float64(coords[3, 1] - coords[2, 1])
    e23y = Float64(coords[3, 2] - coords[2, 2])
    e34x = Float64(coords[4, 1] - coords[3, 1])
    e34y = Float64(coords[4, 2] - coords[3, 2])
    e41x = Float64(coords[1, 1] - coords[4, 1])
    e41y = Float64(coords[1, 2] - coords[4, 2])
    l12 = hypot(e12x, e12y)
    l23 = hypot(e23x, e23y)
    l34 = hypot(e34x, e34y)
    l41 = hypot(e41x, e41y)
    lx = 0.5 * (l12 + l34)
    ly = 0.5 * (l23 + l41)
    lx_span = max(l12, l34)
    ly_span = maximum(@view coords[:, 2]) - minimum(@view coords[:, 2])
    ly_aspect = ly_span > 1e-12 ? ly_span : ly
    ly_long_side = max(l23, l41)
    ly_short_side = min(l23, l41)
    skew = abs(e12x * (-e41x) + e12y * (-e41y)) / max(l12 * l41, 1e-300)
    taper = abs(l23 - l41) / max(0.5 * (l23 + l41), 1e-300)
    taper_width = sqrt(max(lx_span * lx_span - (0.5 * (ly_long_side - ly_short_side))^2, 0.0))
    aspect_taper = taper_width / max(ly_long_side, 1e-300)
    aspect_span = max(lx_span, ly_aspect) / max(min(lx_span, ly_aspect), 1e-300)
    aspect = taper > 1e-12 ? aspect_taper : aspect_span
    diag = hypot(maximum(@view coords[:, 1]) - minimum(@view coords[:, 1]),
                 maximum(@view coords[:, 2]) - minimum(@view coords[:, 2]))
    warp = 0.0
    if size(coords, 2) >= 3
        zmean = sum(@view coords[:, 3]) / 4.0
        warp = maximum(abs(Float64(coords[i, 3]) - zmean) for i in 1:4) / max(diag, 1e-300)
    end
    alpha = 0.0
    beta = 0.0
    gamma = 0.0
    delta = 0.0
    if Cb !== nothing
        D11 = Float64(Cb[1, 1])
        D22 = Float64(Cb[2, 2])
        D12 = Float64(Cb[1, 2])
        D66 = Float64(Cb[3, 3])
        D16 = Float64(Cb[1, 3])
        D26 = Float64(Cb[2, 3])
        if D11 > 0.0 && D22 > 0.0
            alpha = (ly / max(lx, 1e-300)) * (D11 / D22)^(1.0 / 4.0)
            beta = (D12 + 2.0 * D66) / sqrt(D11 * D22)
            gamma = D16 / ((D11^3 * D22)^(1.0 / 4.0))
            delta = D26 / ((D11 * D22^3)^(1.0 / 4.0))
        end
    end
    return (; lx, ly, aspect, skew, taper, warp, alpha, beta, gamma, delta)
end

@inline function _nas_fdkg_flat_feature_values(m)
    aspect = _nas_fdkg_finite(m.aspect)
    aspect2 = aspect * aspect
    inv_aspect = 1.0 / max(aspect, 1e-300)
    inv_aspect2 = 1.0 / max(aspect2, 1e-300)
    skew = _nas_fdkg_finite(m.skew)
    taper = _nas_fdkg_finite(m.taper)
    return (
        1.0,
        aspect,
        aspect2,
        inv_aspect,
        inv_aspect2,
        skew,
        skew * aspect,
        skew * aspect2,
        taper,
        taper * aspect,
        taper * aspect2,
    )
end

@inline function _nas_fdkg_delta_feature_values(m)
    aspect = _nas_fdkg_finite(m.aspect)
    aspect2 = aspect * aspect
    t = max(abs(_nas_fdkg_finite(m.taper)), 0.0)
    st = sqrt(t)
    s = max(abs(_nas_fdkg_finite(m.skew)), 0.0)
    w = max(abs(_nas_fdkg_finite(m.warp)), 0.0)
    geom = sqrt(t * t + s * s + w * w)
    return (
        st,
        t,
        t * t,
        st * aspect,
        t * aspect,
        t * aspect2,
        s,
        s * aspect,
        s * aspect2,
        geom,
        geom * aspect,
        geom * aspect2,
        t * _nas_fdkg_finite(m.alpha),
        t * _nas_fdkg_finite(m.beta),
        t * _nas_fdkg_finite(m.gamma),
        t * _nas_fdkg_finite(m.delta),
    )
end

function _nas_fdkg_eval_component!(K12::AbstractMatrix, coords::AbstractMatrix,
                                   component::Symbol, resultant::Float64, metrics)
    cache = Dict{Symbol,Matrix{Float64}}()
    flat_values = _nas_fdkg_flat_feature_values(metrics)
    delta_values = _nas_fdkg_delta_feature_values(metrics)
    for (term, coeffs) in get(_NAS_FLAT_DELTA_FLAT_COEFFS, component, Tuple{Symbol,NTuple{11,Float64}}[])
        c = 0.0
        @inbounds for i in eachindex(flat_values)
            c += coeffs[i] * flat_values[i]
        end
        abs(c) > 0.0 || continue
        candidate = get!(cache, term) do
            _nas_shape_kg_candidate(coords, term)
        end
        K12 .+= (resultant * c) .* candidate
    end
    for (term, coeffs) in get(_NAS_FLAT_DELTA_DELTA_COEFFS, component, Tuple{Symbol,NTuple{16,Float64}}[])
        c = 0.0
        @inbounds for i in eachindex(delta_values)
            c += coeffs[i] * delta_values[i]
        end
        abs(c) > 0.0 || continue
        candidate = get!(cache, term) do
            _nas_shape_kg_candidate(coords, term)
        end
        K12 .+= (resultant * c) .* candidate
    end
    return K12
end

function geometric_stiffness_quad4_nastran_flat_delta_synth(coords::AbstractMatrix,
                                                            sigma_mem::AbstractVector,
                                                            h::Float64,
                                                            Cb=nothing)
    Kg = zeros(24, 24)
    h > 1e-30 || return Kg
    metrics = _nas_fdkg_metrics(coords, Cb)
    K12 = zeros(12, 12)
    _nas_fdkg_eval_component!(K12, coords, :nxx, Float64(sigma_mem[1]) * h, metrics)
    _nas_fdkg_eval_component!(K12, coords, :nyy, Float64(sigma_mem[2]) * h, metrics)
    _nas_fdkg_eval_component!(K12, coords, :nxy, Float64(sigma_mem[3]) * h, metrics)
    tdofs = (1, 2, 3, 7, 8, 9, 13, 14, 15, 19, 20, 21)
    @inbounds for a in 1:12, b in 1:12
        Kg[tdofs[a], tdofs[b]] = K12[a, b]
    end
    return Kg
end

function geometric_stiffness_quad4_nastran_flat_delta_synth(coords::AbstractMatrix,
                                                            sigma_mem_gp::AbstractMatrix,
                                                            h::Float64,
                                                            Cb=nothing)
    size(sigma_mem_gp, 2) >= 3 || return zeros(24, 24)
    inv_ngp = 1.0 / max(size(sigma_mem_gp, 1), 1)
    sigma_mem = [
        sum(@view sigma_mem_gp[:, 1]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 2]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 3]) * inv_ngp,
    ]
    return geometric_stiffness_quad4_nastran_flat_delta_synth(coords, sigma_mem, h, Cb)
end
